// Compress history + performance into a compact brief for the model.
const hist = $('📋 Read Last 30 Rows').all().map(i=>i.json);
let perf = [];
try { perf = $('📈 Read Performance').all().map(i=>i.json); } catch(e) {}

const recent = hist.slice(-30)
  .map(r => (r.content_brief||'').slice(0,110))
  .filter(Boolean);

// rank hooks by engagement if we have any data yet
const ranked = perf
  .filter(r => r.hook && Number(r.engagement||0) > 0)
  .sort((a,b)=>Number(b.engagement)-Number(a.engagement))
  .slice(0,8)
  .map(r=>`${r.hook} (${r.engagement})`);

// next Monday, in CT
const now = new Date();
const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
d.setUTCDate(d.getUTCDate() + ((8 - d.getUTCDay()) % 7 || 7));
const monday = d.toISOString().slice(0,10);

return [{ json: {
  recent_topics: recent.join(' | ') || 'none yet',
  top_hooks: ranked.join(' | ') || 'no performance data yet',
  week_start: monday,
  posted_count: hist.filter(r=>r.status==='posted').length,
}}];

