let plan={days:[]};
try{ plan=JSON.parse($input.first().json.choices[0].message.content);}catch(e){}
const ctx=$('🧮 Build Context').first().json;

const SOCIAL="bluesky,mastodon,truthsocial,telegram,tumblr";
const BLOGS="blogger,devto,hashnode";

const rows=[];
for(const d of (plan.days||[])){
  const date=d.date||ctx.week_start;
  // morning social slot, every day
  rows.push({
    row_id:`${d.day}-${date}-S`,
    scheduled_datetime:`${date}T08:00:00`,
    platforms:SOCIAL,
    content_mode:"ai_generate",
    campaign_type:d.campaign_type||"education",
    content_brief:d.content_brief||"",
    hook:d.hook||"",
    link_url:"https://nexalead.ai",
    status:"scheduled"
  });
  // midday long-form on the two blog days
  if(d.long_form){
    rows.push({
      row_id:`${d.day}-${date}-B`,
      scheduled_datetime:`${date}T12:00:00`,
      platforms:BLOGS,
      content_mode:"ai_generate",
      campaign_type:d.campaign_type||"education",
      content_brief:(d.content_brief||"")+" Long-form treatment. Each blog must take a DIFFERENT angle on this same topic.",
      hook:d.hook||"",
      link_url:"https://nexalead.ai",
      status:"scheduled"
    });
  }
  // Thursday newsletter
  if(d.day==="THU"){
    rows.push({
      row_id:`THU-${date}-N`,
      scheduled_datetime:`${date}T16:00:00`,
      platforms:"substack",
      content_mode:"ai_generate",
      campaign_type:"education",
      content_brief:(d.content_brief||"")+" Newsletter format, one deployable tactic.",
      hook:d.hook||"",
      link_url:"https://nexalead.ai",
      status:"scheduled"
    });
  }
}
if(!rows.length){
  rows.push({row_id:"FALLBACK-"+ctx.week_start,
    scheduled_datetime:`${ctx.week_start}T08:00:00`,
    platforms:SOCIAL,content_mode:"ai_generate",campaign_type:"proof",
    content_brief:"Planner returned nothing. Write about the $30/month automation stack that replaced a $5,000/month agency, with the exact cost breakdown.",
    hook:"$2.14 ran this all week.",link_url:"https://nexalead.ai",status:"scheduled"});
}
return rows.map(r=>({json:r}));
